begin;
create table public."Dim_Cuenta" (
  "ID_CUENTA" integer generated by default as identity primary key,
  "Id_Empresa" bigint not null,
  "CUENTA" integer not null,
  "CUENTA_PK" bigint not null unique,
  "DESCRIPCION_CUENTA" varchar not null,
  "Id_Cuenta_Comparativo" smallint not null,
  estado smallint not null default 1 check (estado in (0,1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint dim_cuenta_empresa_fkey foreign key ("Id_Empresa") references public."Dim_Empresa"(id_empresa) on update cascade on delete restrict,
  constraint dim_cuenta_comparativo_fkey foreign key ("Id_Cuenta_Comparativo") references public."Dim_Cuenta_Comparativo"("Id_Cuenta_Comparativo") on update cascade on delete restrict
);
comment on table public."Dim_Cuenta" is 'Catálogo de cuentas contables por empresa, vinculadas a Cuenta Comparativo.';
comment on column public."Dim_Cuenta".estado is 'Estado del registro: 1 activo, 0 inactivo.';
comment on column public."Dim_Cuenta".created_at is 'Fecha y hora de creación del registro.';
comment on column public."Dim_Cuenta".updated_at is 'Fecha y hora de la última actualización del registro.';
alter table public."Dim_Cuenta" enable row level security;
revoke all on table public."Dim_Cuenta" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_Cuenta" to authenticated;
create policy dim_cuenta_select_admin on public."Dim_Cuenta" for select to authenticated using ((select private.is_admin()));
create policy dim_cuenta_insert_admin on public."Dim_Cuenta" for insert to authenticated with check ((select private.is_admin()));
create policy dim_cuenta_update_admin on public."Dim_Cuenta" for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_cuenta_delete_admin on public."Dim_Cuenta" for delete to authenticated using ((select private.is_admin()));
create or replace function private.set_dim_cuenta_updated_at() returns trigger language plpgsql set search_path=pg_catalog as $$
begin new.updated_at:=now(); return new; end; $$;
revoke all on function private.set_dim_cuenta_updated_at() from public,anon,authenticated,service_role;
create trigger trg_dim_cuenta_updated_at before update on public."Dim_Cuenta" for each row execute function private.set_dim_cuenta_updated_at();
select setval(pg_get_serial_sequence('public."Dim_Cuenta"','ID_CUENTA'),(select max("ID_CUENTA") from public."Dim_Cuenta"),true);
do $$ declare v_sequence regclass:=pg_get_serial_sequence('public."Dim_Cuenta"','ID_CUENTA'); begin execute format('grant usage, select on sequence %s to authenticated',v_sequence); end; $$;
commit;
